StructuredTextModel.Text:
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:					HE_RT100Status
//	CREATOR:				Helgevold - Jan Magne Dybvik
// REQUIREMENTS: NX CPU
//
// DESCRTIPTION: 	Read RT100 status
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN						DESCRIPTION
//	 1.0					2025-04-01		Jan Magne Dybvik	Initial release
//
//
//================================================================================================================================


CASE Wrk_State OF
	
	// Initialize
	0:
		Clear(Wrk_SendData);
		Clear(Wrk_RecvData);
		Clear(Wrk_RecvString);
		Clear(Wrk_SendString);
		Wrk_RecvSize := 0;
		Wrk_SendSize := 0;
		
		Clear(Out_LinkState);
		Clear(Out_WirelessGen);
		Clear(Out_Operator);
		Out_Signal := 0;
		
		Wrk_State := 10;
		Wrk_TimeInState := T#0s;
		
	// Idle
	10:
		IF Wrk_TimeInState > Cfg_CheckInterval THEN
			Wrk_State := 20;
			Wrk_TimeInState := T#0s;
		END_IF;
		
	//SktTCPConnect
    20:
        Wrk_TCP_Connect := TRUE;
		Wrk_State := 21;
		Wrk_TimeInState := T#0s;
	
	//SktTCP wait completion
	21:
        IF FB_SktTCPConnect.Done THEN
            Wrk_State := 30;
			Wrk_TimeInState := T#0s;
			Wrk_ConnectionError := FALSE;
		ELSIF NOT FB_SktTCPConnect.Busy THEN
			Wrk_State := 10;
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1021_0001;
        ELSIF FB_SktTCPConnect.Error THEN
            Wrk_State := 10;
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1021_0002;
			Wrk_ConnectionError := TRUE;
		ELSIF Wrk_TimeInState > Cfg_Timeout THEN
			Wrk_State := 10; 
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1021_0003;
			Wrk_ConnectionError := TRUE;
    END_IF;

	 //SktTLSConnect
    30:
    Wrk_EstTLSSession := TRUE;
	 Wrk_State := 31;
	Wrk_TimeInState := T#0s;
	
	//SktTLS wait completion
	31:
    IF FB_SktTLSConnect.Done THEN
        Wrk_State := 40;
		Wrk_TimeInState := T#0s;
	ELSIF NOT FB_SktTLSConnect.Busy THEN
		Wrk_State := 90;
		Wrk_TimeInState := T#0s;
		Wrk_ErrorCode := 16#1031_0001;
    ELSIF  FB_SktTLSConnect.Error THEN
        Wrk_State := 90; 
		Wrk_TimeInState := T#0s;
		Wrk_ErrorCode := 16#1031_0002;
	ELSIF Wrk_TimeInState > Cfg_Timeout THEN
		Wrk_State := 90; 
		Wrk_TimeInState := T#0s;
		Wrk_ErrorCode := 16#1031_0003;
    END_IF;

	//SktTLSClearBuf
    40:
        Wrk_SktClearBuffer := TRUE;
		
        IF FB_SktTLSClearBuf.Done THEN
            Wrk_State := 50;
			Wrk_TimeInState := T#0s;
        ELSIF FB_SktTLSClearBuf.Error THEN
            Wrk_State := 80; 
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1040_0001;
		ELSIF Wrk_TimeInState > Cfg_Timeout THEN
			Wrk_State := 80; 
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1040_0002;
        END_IF;

	//SktTLSWrite
    50: 
		Wrk_SendString := HE_RT100BuildRequest(Inp_Command := '/tshoot?format=text&filter=ifaces',
			 Cfg_RT100_IPaddress := Cfg_IP_Adresse,
			 Cfg_Port := Cfg_Port);
		ToAryByte(Wrk_SendString, _LOW_HIGH, Wrk_SendData[0]);
		Wrk_SendSize :=GetByteLen(In:=Wrk_SendString);
        Wrk_TLSSend := TRUE;
		
		Wrk_State := 51;
		Wrk_TimeInState := T#0s;
	
	//SktTLS write - wait completion
	51:
        IF FB_SktTLSWrite.Done THEN
            Wrk_State := 60;
			Wrk_TimeInState := T#0s;
		ELSIF NOT FB_SktTLSWrite.Busy THEN
			Wrk_State := 80;
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1051_0001;
        ELSIF  FB_SktTLSWrite.Error THEN
              Wrk_State := 80; 
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1051_0002;
		ELSIF Wrk_TimeInState > Cfg_Timeout THEN
			Wrk_State := 80; 
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1051_0003;
        END_IF;


	//SktTLSRead
    60:
        Wrk_TLSRecv := TRUE;
		
		Wrk_State := 61;
		Wrk_TimeInState := T#0s;
	
	//SktTLS read - wait completion
	61:
        IF FB_SktTLSRead.Done THEN
			Wrk_RecvString:= AryToString(In:=Wrk_RecvData[0], Size :=Min(SizeOfAry( In:=Wrk_RecvData ), UINT#1985));
			IF 0 < FIND(In1:=Wrk_RecvString, In2:='200 OK') THEN
	            Wrk_State := 70;
				Wrk_TimeInState := T#0s;
			ELSE
				Wrk_State := 80;
				Wrk_TimeInState := T#0s;
				Wrk_ErrorCode := 16#1061_0001;
			END_IF;
		ELSIF NOT FB_SktTLSRead.Busy THEN
			Wrk_State := 80;
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1061_0002;
        ELSIF FB_SktTLSRead.Error THEN
            Wrk_State := 80; 
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1061_0003;
		ELSIF Wrk_TimeInState > Cfg_Timeout THEN
			Wrk_State := 80; 
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1061_0004;
        END_IF;
	
	// Parse Data
	70:
		
		IF HE_RT100ParseIfaces(
			Inp_RecvString := Wrk_RecvString,
			Out_LinkState => Wrk_LinkState,
			Out_WirelessGen => Wrk_WirelessGen,
			Out_Operator => Wrk_Operator,
			Out_Signal => Wrk_Signal)
		THEN
			Out_LinkState := Wrk_LinkState;
			Out_WirelessGen := Wrk_WirelessGen;
			Out_Operator := Wrk_Operator;
			Out_Signal := Wrk_Signal;
		END_IF;
		Wrk_State := 80;
		Wrk_TimeInState := T#0s;
		
	//SktTLSDisconnect
    80:
        Wrk_EndTLSSession := TRUE;
		
        IF FB_SktTLSDisconnect.Done THEN
            Wrk_State := 90;
			Wrk_TimeInState := T#0s;
        ELSIF FB_SktTLSDisconnect.Error THEN
             Wrk_State := 90; 
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1080_0001;
		ELSIF Wrk_TimeInState > Cfg_Timeout THEN
			Wrk_State := 90; 
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1080_0002;
        END_IF;

	//SktClose
    90: 
        Wrk_CloseSocket := TRUE;
		
        IF FB_SktClose.Done THEN
            Wrk_State := 10;
			Wrk_TimeInState := T#0s;
        ELSIF FB_SktClose.Error THEN
            Wrk_State := 10; 
			Wrk_TimeInState := T#0s;
			Wrk_ErrorCode := 16#1090_0001;
        END_IF;

//Out of bounds
ELSE
	Wrk_State := 0;
	Wrk_TimeInState := T#0s;
	Wrk_ErrorCode := 16#FFFF_FFFF;
		
END_CASE;


 // Get Interval Time
 Wrk_TaskIntervalTime := GetMyTaskInterval();
 // Increment state time
 Wrk_TimeInState :=  ADD_TIME(In1:=Wrk_TimeInState, In2:=Wrk_TaskIntervalTime);


FB_SktTCPConnect(
    Execute :=Wrk_TCP_Connect,
    SrcTcpPort :=UINT#0, //own TCP port number(auto allocation)
    DstAdr :=Cfg_IP_Adresse, //target IP Address or host name
    DstTcpPort :=Cfg_Port, //target TCP port number
    Socket =>Wrk_Socket ); //socket variable

FB_SktTLSConnect(
    Execute :=Wrk_EstTLSSession,
    Socket :=Wrk_Socket, //socket variable
    TLSSessionName :=Cfg_TLSSession, //TLS session name
    Handle =>Wrk_SessionHandle ); //TLS session handle
	
FB_SktTLSClearBuf(
    Execute :=Wrk_SktClearBuffer,
    Handle :=Wrk_SessionHandle); //TLS session handle
	
FB_SktTLSWrite(
    Execute :=Wrk_TLSSend,
    Handle :=Wrk_SessionHandle, //TLS session handle
    SendDat :=Wrk_SendData[0], //sending data
    SendDatSize :=Wrk_SendSize ); //sending data size
	
FB_SktTLSRead(
    Execute :=Wrk_TLSRecv,
    Handle :=Wrk_SessionHandle, //TLS session handle
    TimeOut :=TLS_TIMEOUT, //timeout time
    RcvDatSize :=SizeOfAry( In:=Wrk_RecvData ), //receive buffer size
    RcvDat :=Wrk_RecvData[0], //receiving data
    RcvSize =>Wrk_RecvSize ); //receiving data size
	
FB_SktTLSDisconnect(
    Execute :=Wrk_EndTLSSession,
    Handle :=Wrk_SessionHandle ); //TLS session handle
	
FB_SktClose(
    Execute :=Wrk_CloseSocket,
    Socket :=Wrk_Socket ); //socket variable
	
// Clear Execution bits
Wrk_TCP_Connect :=FALSE;
Wrk_EstTLSSession := FALSE;
Wrk_SktClearBuffer := FALSE;
Wrk_TLSSend := FALSE;
Wrk_TLSRecv := FALSE;
Wrk_EndTLSSession := FALSE;
Wrk_CloseSocket := FALSE;

Sts_ConnectionError := Wrk_ConnectionError;
